// 1. Input Validation & Fault Handling
if (qs_input.current_q_bi == NULL || qs_input.target_q_bi == NULL) {
    qs_state.mode = QS_FAULT;
    qs_output.mode = QS_FAULT;
    qs_output.settled = FALSE32;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = FALSE32;
    qs_output.slew_axis.x = 0.0; qs_output.slew_axis.y = 0.0; qs_output.slew_axis.z = 0.0;
    qs_output.command_q_bi.w = 1.0; qs_output.command_q_bi.x = 0.0; qs_output.command_q_bi.y = 0.0; qs_output.command_q_bi.z = 0.0;
    return;
}

double current_w = qs_input.current_q_bi->w;
double current_x = qs_input.current_q_bi->x;
double current_y = qs_input.current_q_bi->y;
double current_z = qs_input.current_q_bi->z;
double target_w = qs_input.target_q_bi->w;
double target_x = qs_input.target_q_bi->x;
double target_y = qs_input.target_q_bi->y;
double target_z = qs_input.target_q_bi->z;

if (!isfinite(current_w) || !isfinite(current_x) || !isfinite(current_y) || !isfinite(current_z) ||
    !isfinite(target_w) || !isfinite(target_x) || !isfinite(target_y) || !isfinite(target_z)) {
    qs_state.mode = QS_FAULT;
    qs_output.mode = QS_FAULT;
    qs_output.settled = FALSE32;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = FALSE32;
    qs_output.slew_axis.x = 0.0; qs_output.slew_axis.y = 0.0; qs_output.slew_axis.z = 0.0;
    qs_output.command_q_bi.w = 1.0; qs_output.command_q_bi.x = 0.0; qs_output.command_q_bi.y = 0.0; qs_output.command_q_bi.z = 0.0;
    return;
}

double max_rate = qs_config.max_rate_rad_cycle;
double max_accel = qs_config.max_accel_rad_cycle2;
double settle_angle = qs_config.settle_angle_rad;
double settle_rate = qs_config.settle_rate_rad_cycle;
unint32 settle_cycles_req = qs_config.settle_cycles;

if (!isfinite(max_rate) || max_rate <= 0.0 || max_rate > PI ||
    !isfinite(max_accel) || max_accel <= 0.0 ||
    !isfinite(settle_angle) || settle_angle < 0.0 ||
    !isfinite(settle_rate) || settle_rate < 0.0 || settle_rate > max_rate ||
    !isfinite((double)settle_cycles_req) || settle_cycles_req < 1 || settle_cycles_req > 20) {
    qs_state.mode = QS_FAULT;
    qs_output.mode = QS_FAULT;
    qs_output.settled = FALSE32;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = FALSE32;
    qs_output.slew_axis.x = 0.0; qs_output.slew_axis.y = 0.0; qs_output.slew_axis.z = 0.0;
    qs_output.command_q_bi.w = 1.0; qs_output.command_q_bi.x = 0.0; qs_output.command_q_bi.y = 0.0; qs_output.command_q_bi.z = 0.0;
    return;
}

// 2. State Initialization / Reset Logic
int reversal_reset = FALSE32;

// If entering from HOLD or first call, clear history
if (qs_state.mode == QS_HOLD || !qs_state.axis_valid) {
    qs_state.commanded_rate_rad_cycle = 0.0;
    qs_state.previous_axis.x = 0.0; qs_state.previous_axis.y = 0.0; qs_state.previous_axis.z = 0.0;
    qs_state.axis_valid = TRUE32;
    qs_state.settled = 0;
}

// 3. Compute Relative Attitude and Angle
adcs_quat_t q_curr_norm, q_target_norm, q_rel;

if (adcs_quat_normalize(qs_input.current_q_bi, &q_curr_norm) != ADCS_OK) {
     qs_state.mode = QS_FAULT;
     qs_output.mode = QS_FAULT;
     qs_output.settled = FALSE32;
     qs_output.error_angle_rad = 0.0;
     qs_output.applied_step_rad = 0.0;
     qs_output.commanded_rate_rad_cycle = 0.0;
     qs_output.braking_rate_rad_cycle = 0.0;
     qs_output.reversal_reset = FALSE32;
     qs_output.slew_axis.x = 0.0; qs_output.slew_axis.y = 0.0; qs_output.slew_axis.z = 0.0;
     qs_output.command_q_bi.w = 1.0; qs_output.command_q_bi.x = 0.0; qs_output.command_q_bi.y = 0.0; qs_output.command_q_bi.z = 0.0;
     return;
}
if (adcs_quat_normalize(qs_input.target_q_bi, &q_target_norm) != ADCS_OK) {
     qs_state.mode = QS_FAULT;
     qs_output.mode = QS_FAULT;
     qs_output.settled = FALSE32;
     qs_output.error_angle_rad = 0.0;
     qs_output.applied_step_rad = 0.0;
     qs_output.commanded_rate_rad_cycle = 0.0;
     qs_output.braking_rate_rad_cycle = 0.0;
     qs_output.reversal_reset = FALSE32;
     qs_output.slew_axis.x = 0.0; qs_output.slew_axis.y = 0.0; qs_output.slew_axis.z = 0.0;
     qs_output.command_q_bi.w = 1.0; qs_output.command_q_bi.x = 0.0; qs_output.command_q_bi.y = 0.0; qs_output.command_q_bi.z = 0.0;
     return;
}

adcs_quat_t q_curr_conj = adcs_quat_conjugate(&q_curr_norm);
q_rel = adcs_quat_multiply(&q_target_norm, &q_curr_conj);

double w = q_rel.w;
if (w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}
w = q_rel.w;

double angle = 2.0 * acos(w);
if (angle < 0.0) angle = 0.0;
if (angle > PI) angle = PI;

adcs_vec3_t rel_axis;
double sin_half_angle = sqrt(1.0 - w*w);

if (sin_half_angle > ADCS_EPS_NORM) {
    rel_axis.x = q_rel.x / sin_half_angle;
    rel_axis.y = q_rel.y / sin_half_angle;
    rel_axis.z = q_rel.z / sin_half_angle;
} else {
    rel_axis.x = 1.0; rel_axis.y = 0.0; rel_axis.z = 0.0;
}

// 4. Reversal Check
if (qs_state.axis_valid) {
    double dot = adcs_vec3_dot(&rel_axis, &qs_state.previous_axis);
    if (dot < 0.0) {
        qs_state.commanded_rate_rad_cycle = 0.0;
        reversal_reset = TRUE32;
    }
}

// 5. Profile Planning
double braking_envelope = sqrt(2.0 * max_accel * angle);
double target_rate = (max_rate < braking_envelope) ? max_rate : braking_envelope;

double current_rate = qs_state.commanded_rate_rad_cycle;
double new_rate = current_rate;

if (current_rate < target_rate) {
    double proposed = current_rate + max_accel;
    new_rate = (proposed < target_rate) ? proposed : target_rate;
} else if (current_rate > target_rate) {
    double proposed = current_rate - max_accel;
    new_rate = (proposed > target_rate) ? proposed : target_rate;
}

qs_state.commanded_rate_rad_cycle = new_rate;

// Determine Mode
qs_mode_t mode = qs_state.mode;
if (mode != QS_SETTLE) {
    if (new_rate < target_rate) {
        mode = QS_ACCEL;
    } else if (new_rate > target_rate) {
        mode = QS_DECEL;
    } else {
        mode = QS_CRUISE;
    }
}
qs_state.mode = mode;

// 6. Apply Step
double step = (new_rate < angle) ? new_rate : angle;

double half_step = 0.5 * step;
double c_hs = cos(half_step);
double s_hs = sin(half_step);

adcs_quat_t dq_cmd;
dq_cmd.w = c_hs;
dq_cmd.x = rel_axis.x * s_hs;
dq_cmd.y = rel_axis.y * s_hs;
dq_cmd.z = rel_axis.z * s_hs;

qs_output.command_q_bi = dq_cmd;

qs_state.previous_axis = rel_axis;
qs_state.axis_valid = TRUE32;

// 7. Settling Logic
unint32 settled_flag = FALSE32;
if (mode != QS_HOLD) {
    if (angle <= settle_angle && new_rate <= settle_rate) {
        if (qs_state.mode == QS_SETTLE) {
            qs_state.settled++;
            if (qs_state.settled >= settle_cycles_req) {
                qs_state.mode = QS_HOLD;
                qs_state.settled = 0;
                settled_flag = TRUE32;
            }
        } else {
            qs_state.mode = QS_SETTLE;
            qs_state.settled = 1;
            if (settle_cycles_req == 1) {
                 qs_state.mode = QS_HOLD;
                 qs_state.settled = 0;
                 settled_flag = TRUE32;
            }
        }
    } else {
        qs_state.settled = 0;
        if (qs_state.mode == QS_SETTLE) {
             qs_state.mode = QS_CRUISE;
        }
    }
}
qs_output.settled = settled_flag;

// 8. Fill Output
qs_output.mode = qs_state.mode;
qs_output.error_angle_rad = angle;
qs_output.applied_step_rad = step;
qs_output.commanded_rate_rad_cycle = new_rate;
qs_output.braking_rate_rad_cycle = braking_envelope;
qs_output.reversal_reset = reversal_reset;
qs_output.slew_axis = rel_axis;

