    double s = sqrt(1.0 - rel_q.w * rel_q.w);
    if (s < ADCS_EPS_QUAT) {
         slew_axis = (adcs_vec3_t){1, 0, 0};
    } else {
        slew_axis = adcs_vec3_scale(&(adcs_vec3_t){rel_q.x, rel_q.y, rel_q.z}, 1.0 / s);
