double target_rate = (max_rate < braking_envelope) ? max_rate : braking_envelope;

double prev_rate = qs_state.commanded_rate_rad_cycle;
if (prev_rate < target_rate) {
    qs_state.commanded_rate_rad_cycle = (prev_rate + max_accel < target_rate) ? prev_rate + max_accel : target_rate;
} else {
    qs_state.commanded_rate_rad_cycle = (prev_rate - max_accel > target_rate) ? prev_rate - max_accel : target_rate;
}

