if (qs_output.error_angle_rad <= settle_angle && current_rate <= settle_rate) {
    if (qs_state.mode == QS_SETTLE) {
        qs_state.settled++;
        if (qs_state.settled >= settle_cycles_req) {
            qs_output.mode = QS_HOLD;
            qs_output.settled = 1;
            qs_state.settled = 0;
            qs_state.commanded_rate_rad_cycle = 0.0;
        } else {
            qs_output.mode = QS_SETTLE;
            qs_output.settled = 0;
        }
    } else {
        qs_state.mode = QS_SETTLE;
        qs_state.settled = 1;
        qs_output.mode = QS_SETTLE;
        qs_output.settled = 0;
    }
} else {
    qs_state.mode = QS_HOLD; 
    qs_state.settled = 0;
    qs_output.settled = 0;
    if (qs_output.mode == QS_SETTLE) {
         qs_output.mode = QS_HOLD; // Revert to hold if we were settling but left window
    }
}
